import type {
  DeliveryUrl,
  MediaRemoveResult,
  NormalizedProfileImage,
  NormalizedProviderImage,
  ProviderImagePurpose,
  ProviderMediaOwnerType,
  ProviderMediaSafeView,
  StoredMediaReference,
  StoredProviderVideoReference,
} from "./media.types.js";

export interface StoreProfileImageInput {
  readonly bytes: Buffer;
  readonly ownerUserId: string;
  readonly mediaId: string;
  /** Opaque storage key generated by the media module before upload. */
  readonly storageKey: string;
}

export interface StoreProviderImageStorageInput
  extends StoreProfileImageInput {
  readonly purpose: ProviderImagePurpose;
}

/** Media-owned storage + signed delivery. Customers own association only. */
export interface MediaStoragePort {
  storeProfileImage(input: StoreProfileImageInput): Promise<StoredMediaReference>;
  /** Optional for customer-only storage fakes; required by production Provider image wiring. */
  storeProviderImage?(
    input: StoreProviderImageStorageInput,
  ): Promise<StoredMediaReference>;
  /** Optional for customer-only storage fakes; required by production Provider video wiring. */
  storeProviderVideo?(input: StoreProviderVideoInput): Promise<StoredProviderVideoReference>;
  createAuthorizedDeliveryUrl(
    reference: Pick<StoredMediaReference, "provider" | "storageKey">,
    expiresAt: Date,
  ): Promise<DeliveryUrl>;
  /** Cloudinary-derived, signed thumbnail for an authenticated video. */
  createAuthorizedVideoThumbnailUrl?(
    reference: Pick<StoredProviderVideoReference, "provider" | "storageKey">,
    expiresAt: Date,
  ): Promise<DeliveryUrl>;
  createAuthorizedVideoDeliveryUrl?(
    reference: Pick<StoredProviderVideoReference, "provider" | "storageKey">,
    expiresAt: Date,
  ): Promise<DeliveryUrl>;
  remove(
    reference: Pick<StoredMediaReference, "provider" | "storageKey">,
  ): Promise<MediaRemoveResult>;
}

export interface ProfileImageProcessor {
  normalize(input: Buffer): Promise<NormalizedProfileImage>;
}

/** Sharp-owned Provider image normalize at fixed logo/cover/gallery sizes. */
export interface ProviderImageProcessor {
  normalize(input: {
    readonly purpose: ProviderImagePurpose;
    readonly bytes: Buffer;
  }): Promise<NormalizedProviderImage>;
}

export interface ReserveProviderMediaInput {
  readonly mediaId: string;
  readonly ownerUserId: string;
  readonly ownerType: ProviderMediaOwnerType;
  readonly contentType: string;
  readonly byteSize: number;
  readonly width?: number | null;
  readonly height?: number | null;
}

export interface StoreProviderImageInput {
  readonly mediaId: string;
  readonly ownerUserId: string;
  readonly purpose: ProviderImagePurpose;
  readonly bytes: Buffer;
  /** Opaque storage key generated by the media module before upload. */
  readonly storageKey: string;
}

export interface StoreProviderVideoInput {
  readonly mediaId: string;
  readonly ownerUserId: string;
  readonly bytes: Buffer;
  readonly contentType: "video/mp4" | "video/webm";
  /** Opaque storage key generated by the media module before upload. */
  readonly storageKey: string;
}

export interface FinalizeProviderVideoInput {
  readonly mediaId: string;
}

/**
 * Media-owned Provider operations. Callers must already authorize the business
 * purpose; Media never decides Provider membership or application state.
 * Public results never include storage keys.
 */
export interface ProviderMediaPort {
  normalizeProviderImage(input: {
    readonly purpose: ProviderImagePurpose;
    readonly bytes: Buffer;
  }): Promise<NormalizedProviderImage>;

  reserveProviderMedia(
    input: ReserveProviderMediaInput,
  ): Promise<ProviderMediaSafeView>;

  storeProviderImage(
    input: StoreProviderImageInput,
  ): Promise<ProviderMediaSafeView>;

  /**
   * Reserve + upload path for Provider gallery video. Leaves status PROCESSING
   * until finalizeProviderVideo succeeds or marks FAILED.
   */
  storeProviderVideo(
    input: StoreProviderVideoInput,
  ): Promise<ProviderMediaSafeView>;

  /**
   * Finalizes authoritative Cloudinary video metadata and derived thumbnail.
   * May be stubbed until Cloudinary video wiring is complete.
   */
  finalizeProviderVideo(
    input: FinalizeProviderVideoInput,
  ): Promise<ProviderMediaSafeView>;

  createSignedDeliveryUrl(
    mediaId: string,
    expiresAt: Date,
  ): Promise<DeliveryUrl>;

  createSignedThumbnailUrl(
    mediaId: string,
    expiresAt: Date,
  ): Promise<DeliveryUrl>;

  markPendingDelete(mediaId: string): Promise<void>;

  cleanupBoundedPending(
    limit?: number,
  ): Promise<{ readonly processed: number }>;
}
